import { Suspense } from 'react'
import { unstable_prefetch } from 'next/cache'
import { getRelatedProducts } from '@/lib/data'

export default function ProductPage() {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products...</p>}>
          {/* the fallback is in the App Shell, the related products are not */}
          <RelatedProducts />
        </Suspense>
      </section>
    </main>
  )
}

async function RelatedProducts() {
  await unstable_prefetch() // below this renders on a per-link prefetch, not in the App Shell
  const relatedProducts = await getRelatedProducts()

  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

